import { Actor, Document } from './types';
import { DocumentRepository } from './repository';

export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}

  archive(actor: Actor, id: string): void {
    const document = this.repository.find(id);
    if (!this.isVisible(actor, document)) throw new Error('not found');
    const visible = document as Document;
    if (!this.isAllowed(actor, visible)) throw new Error('forbidden');
    if (visible.archived) return;
    this.repository.archive(visible, actor.user);
  }

  private isVisible(actor: Actor, document: Document | undefined): boolean {
    return !!document && !document.deleted && document.tenant === actor.tenant;
  }

  private isAllowed(actor: Actor, document: Document): boolean {
    switch (actor.role) {
      case 'admin': return true;
      case 'editor': return document.owner === actor.user;
      case 'viewer': return false;
    }
  }
}
